body.content:
:root{
  --a3g-dark:#091522;
  --a3g-dark2:#10263a;
  --a3g-orange:#ff4a1f;
  --a3g-line:#e6ebf0;
  --a3g-muted:#6f7b88;
  --a3g-bg:#f5f7fa;
  --a3g-shadow:0 14px 38px rgba(15,30,48,.08);
}
.a3garage-hero{padding:48px 0 34px;background:
  radial-gradient(circle at 12% 0%,rgba(255,74,31,.18),transparent 28%),
  linear-gradient(135deg,#07131f,#10283d);color:#fff}
.a3garage-hero-inner{display:flex;align-items:center;justify-content:space-between;gap:28px}
.a3garage-hero span{display:inline-flex;color:#ff9b80;font-size:10px;font-weight:900;letter-spacing:.12em}
.a3garage-hero h1{font-family:"Alexandria",sans-serif;font-size:clamp(34px,5vw,56px);line-height:1.25;margin:7px 0}
.a3garage-hero p{max-width:820px;color:#b9c5d1;margin:0;font-size:14px}
.a3garage-hero-badge{min-width:220px;padding:16px 18px;border-radius:16px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.09)}
.a3garage-hero-badge b,.a3garage-hero-badge small{display:block}.a3garage-hero-badge small{margin-top:3px;color:#9fb0c0;font-size:10px}
.a3garage-shell{padding:28px 0 70px}
.a3garage-login{max-width:700px;margin:30px auto;padding:45px 28px;text-align:center;background:#fff;border:1px solid var(--a3g-line);border-radius:20px;box-shadow:var(--a3g-shadow)}
.a3garage-login-icon{font-size:56px}.a3garage-login h2{font-family:"Alexandria";margin:8px 0}.a3garage-login p{color:var(--a3g-muted)}
.a3garage-login a,.a3garage-primary{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:10px;background:linear-gradient(135deg,var(--a3g-orange),#ff6c36);color:#fff!important;padding:10px 15px;font-weight:900;text-decoration:none}
.a3garage-login-icon{width:58px;height:58px;margin:0 auto;display:grid;place-items:center;border-radius:18px;background:#0c2032;color:#fff;font-family:"Alexandria";font-size:20px!important;font-weight:900}
.a3garage-onboarding{max-width:560px;margin:18px auto;display:grid;grid-template-columns:repeat(3,1fr);gap:8px;text-align:right}
.a3garage-onboarding span{display:flex;align-items:flex-start;gap:7px;padding:11px;border:1px solid #edf1f4;border-radius:11px;background:#fafbfd;color:#4d5d6d;font-size:9px;line-height:1.7}
.a3garage-onboarding b{flex:0 0 auto;width:21px;height:21px;border-radius:50%;display:grid;place-items:center;background:#ffe9e1;color:#d7461d;font-size:8px}
.a3garage-login-actions{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
.a3garage-login-actions a.is-secondary{background:#eef3f7;color:#263d53!important}
.a3garage-toolbar{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:15px}
.a3garage-toolbar span,.a3garage-section-head span{font-size:9px;color:var(--a3g-orange);font-weight:900;letter-spacing:.08em}
.a3garage-toolbar h2{font-family:"Alexandria";margin:2px 0 0;font-size:25px}
.a3garage-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}
.a3garage-stats>div{padding:16px;border:1px solid var(--a3g-line);background:#fff;border-radius:14px;box-shadow:0 5px 18px rgba(15,30,48,.035)}
.a3garage-stats small{display:block;color:#84909d;font-size:9px}.a3garage-stats strong{display:block;font-family:"Alexandria";font-size:22px;margin-top:3px}
.a3garage-layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:14px;align-items:start}
.a3garage-sidebar,.a3garage-main{background:#fff;border:1px solid var(--a3g-line);border-radius:17px;box-shadow:0 6px 24px rgba(15,30,48,.04)}
.a3garage-sidebar{padding:13px;position:sticky;top:118px}
.a3garage-main{padding:18px;min-height:520px}
.a3garage-side-head{display:flex;justify-content:space-between;align-items:center;padding:2px 2px 10px}
.a3garage-side-head strong{font-family:"Alexandria";font-size:13px}.a3garage-side-head button{width:29px;height:29px;border:0;border-radius:8px;background:#eef3f7;color:#23394f;font-weight:900}
.a3garage-vehicles{display:grid;gap:8px}
.a3garage-vehicle-card{width:100%;display:flex;align-items:center;gap:10px;padding:10px;border-radius:11px;border:1px solid #edf1f4;background:#fbfcfd;text-align:right;transition:.18s}
.a3garage-vehicle-card:hover,.a3garage-vehicle-card.is-active{border-color:#ffc7b5;background:#fff5f1}
.a3garage-vehicle-icon{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:#eef2f6;font-size:20px}
.a3garage-vehicle-copy{min-width:0;flex:1}.a3garage-vehicle-copy b{display:block;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.a3garage-vehicle-copy small{display:block;color:#8a96a3;font-size:8px;margin-top:2px}
.a3garage-side-empty{padding:20px 10px;text-align:center;color:#8a96a3;font-size:10px}
.a3garage-skeleton{height:58px;border-radius:10px;background:linear-gradient(90deg,#f1f4f6,#e8edf1,#f1f4f6);background-size:200% 100%;animation:a3s 1.3s infinite}
@keyframes a3s{to{background-position:-200% 0}}
.a3garage-empty{padding:70px 20px;text-align:center}.a3garage-empty>span{font-size:56px}.a3garage-empty h2{font-family:"Alexandria";margin:7px 0}.a3garage-empty p{max-width:570px;margin:0 auto 14px;color:var(--a3g-muted)}
.a3garage-vehicle-hero{display:flex;align-items:start;justify-content:space-between;gap:20px;padding:18px;border-radius:15px;background:linear-gradient(135deg,#0b1c2b,#16334c);color:#fff}
.a3garage-vehicle-hero>div>span{font-size:9px;color:#ff9d81;font-weight:900}.a3garage-vehicle-hero h2{font-family:"Alexandria";font-size:25px;margin:3px 0}
.a3garage-vehicle-meta{display:flex;gap:7px;flex-wrap:wrap}.a3garage-vehicle-meta span{padding:4px 7px;border-radius:999px;background:rgba(255,255,255,.08);color:#cfdae3;font-size:8px}
.a3garage-vehicle-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}
.a3garage-vehicle-actions button{border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.07);color:#fff;border-radius:9px;padding:8px 10px;font-size:9px;font-weight:800}
.a3garage-vehicle-actions .a3garage-sell{background:var(--a3g-orange);border-color:var(--a3g-orange)}
.a3garage-next{display:grid;grid-template-columns:105px 1fr;gap:18px;align-items:center;padding:18px;margin-top:14px;border:1px solid var(--a3g-line);border-radius:15px;background:#fafbfd}
.a3garage-next-ring{--a3-progress:0deg;width:92px;height:92px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--a3g-orange) var(--a3-progress),#e8edf1 0);position:relative}
.a3garage-next-ring:before{content:"";position:absolute;inset:9px;border-radius:50%;background:#fff}.a3garage-next-ring span{position:relative;z-index:2;font-family:"Alexandria";font-weight:800;font-size:15px}
.a3garage-next>div:last-child>span{color:var(--a3g-orange);font-size:9px;font-weight:900}.a3garage-next h3{font-family:"Alexandria";margin:3px 0;font-size:17px}.a3garage-next p{margin:0;color:#7c8794;font-size:10px}
.a3garage-section-head{display:flex;align-items:end;justify-content:space-between;gap:15px;margin:20px 0 11px}.a3garage-section-head h3{font-family:"Alexandria";margin:2px 0 0;font-size:19px}
.a3garage-legend{display:flex;align-items:center;gap:6px;color:#7a8794;font-size:8px}.a3garage-legend i{width:7px;height:7px;border-radius:50%;display:inline-block}.a3garage-legend .is-due{background:#dc2626}.a3garage-legend .is-soon{background:#f59e0b}.a3garage-legend .is-ok{background:#16a34a}
.a3garage-maintenance{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.a3garage-maint-card{padding:14px;border:1px solid var(--a3g-line);border-right:4px solid #16a34a;border-radius:13px;background:#fff}
.a3garage-maint-card.is-due{border-right-color:#dc2626}.a3garage-maint-card.is-soon{border-right-color:#f59e0b}
.a3garage-maint-top{display:flex;align-items:center;justify-content:space-between;gap:8px}
.a3garage-maint-status,.a3garage-maint-kind{font-size:8px;font-weight:900}.a3garage-maint-card.is-due .a3garage-maint-status{color:#dc2626}.a3garage-maint-card.is-soon .a3garage-maint-status{color:#b76b00}.a3garage-maint-card.is-upcoming .a3garage-maint-status{color:#108148}.a3garage-maint-kind{color:#8b96a2}
.a3garage-maint-card h4{font-family:"Alexandria";font-size:13px;margin:7px 0}
.a3garage-progress{height:6px;background:#edf1f4;border-radius:999px;overflow:hidden}.a3garage-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--a3g-orange),#ff8d68);border-radius:inherit}
.a3garage-maint-facts{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-top:10px}.a3garage-maint-facts span{padding:7px;border-radius:8px;background:#f7f9fb}.a3garage-maint-facts small{display:block;color:#8b96a2;font-size:7px}.a3garage-maint-facts b{display:block;font-size:9px;margin-top:1px}
.a3garage-maintenance-empty,.a3garage-loading{grid-column:1/-1;padding:28px;border:1px dashed #dfe5ea;border-radius:13px;background:#fafbfd;text-align:center;color:#7b8793}.a3garage-maintenance-empty span{font-size:32px}.a3garage-maintenance-empty h4{font-family:"Alexandria";margin:5px 0}.a3garage-maintenance-empty p{font-size:10px;max-width:600px;margin:auto}
.a3garage-quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:18px}
.a3garage-quick-grid a{padding:14px;border:1px solid var(--a3g-line);border-radius:12px;background:#fbfcfd;text-align:center}.a3garage-quick-grid span{display:block;font-size:25px}.a3garage-quick-grid b{display:block;font-size:10px;margin-top:4px}.a3garage-quick-grid small{display:block;color:#8b96a2;font-size:7px;margin-top:2px}
.a3garage-dialog{border:0;padding:0;border-radius:18px;max-width:760px;width:min(760px,calc(100% - 24px));box-shadow:0 28px 90px rgba(0,0,0,.25)}.a3garage-dialog::backdrop{background:rgba(5,12,20,.62);backdrop-filter:blur(4px)}
.a3garage-dialog-card{padding:20px;margin:0;background:#fff}.a3garage-dialog-head{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:12px}.a3garage-dialog-head span{font-size:8px;color:var(--a3g-orange);font-weight:900}.a3garage-dialog-head h3{font-family:"Alexandria";margin:2px 0;font-size:20px}.a3garage-dialog-head>button{width:31px;height:31px;border:0;border-radius:8px;background:#eef2f5;font-size:20px}
.a3garage-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.a3garage-form-grid label,.a3garage-wide-label{display:block}.a3garage-form-grid label>span,.a3garage-wide-label>span{display:block;color:#526170;font-size:9px;font-weight:800;margin-bottom:4px}.a3garage-form-grid input,.a3garage-form-grid select,.a3garage-form-grid textarea,.a3garage-wide-label input{width:100%;border:1px solid #dde4ea;border-radius:9px;background:#fff;padding:9px 10px;outline:0}.a3garage-form-grid input:focus,.a3garage-form-grid select:focus,.a3garage-form-grid textarea:focus,.a3garage-wide-label input:focus{border-color:#ff9c7f;box-shadow:0 0 0 3px rgba(255,74,31,.08)}
.a3garage-span-2{grid-column:1/-1}.a3garage-dialog-actions{display:flex;justify-content:flex-end;gap:7px;margin-top:15px}.a3garage-dialog-actions button{border:0;border-radius:9px;padding:9px 12px;font-weight:800}.a3garage-dialog-actions button:not(.a3garage-primary){background:#eef2f5;color:#344556}
.a3garage-form-message{margin-top:8px;font-size:9px;color:#168147}.a3garage-form-message.is-error{color:#c62828}.a3garage-safety-note{margin-top:12px;padding:10px;border-radius:9px;background:#fff8f5;border:1px solid #ffd7ca;color:#765349;font-size:9px}
@media(max-width:960px){.a3garage-layout{grid-template-columns:1fr}.a3garage-sidebar{position:static}.a3garage-vehicles{display:flex;overflow-x:auto}.a3garage-vehicle-card{min-width:220px}.a3garage-maintenance{grid-template-columns:1fr}.a3garage-quick-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){.a3garage-hero-inner{align-items:flex-start;flex-direction:column}.a3garage-hero-badge{min-width:0;width:100%}.a3garage-stats{grid-template-columns:1fr 1fr}.a3garage-vehicle-hero{flex-direction:column}.a3garage-vehicle-actions{justify-content:flex-start}.a3garage-next{grid-template-columns:82px 1fr}.a3garage-next-ring{width:74px;height:74px}.a3garage-maint-facts{grid-template-columns:1fr}.a3garage-section-head{align-items:flex-start;flex-direction:column}.a3garage-form-grid{grid-template-columns:1fr}.a3garage-span-2{grid-column:auto}.a3garage-quick-grid{grid-template-columns:1fr 1fr}}

@media(max-width:700px){.a3garage-onboarding{grid-template-columns:1fr}}
